const MESSAGE_URL_PATTERN=/(https?:\/\/[^\s<]+|(?:file:\/\/\/|\/(?:Users|private|tmp|var|Volumes)\/)[^\s<>"'`]+(?:[ \t]+(?!\/(?:Users|private|tmp|var|Volumes)\/)[^\s<>"'`]+)*?[ \t]*\.[A-Za-z0-9]{1,16}(?=$|[\s<>"'`.,!?;:)])|file:\/\/\/[^\s<>"'`]+|\/(?:Users|private|tmp|var|Volumes)\/[^\s<>"'`]+)/g;
const stripUrlPunctuation=(value:string)=>{const match=value.match(/[.,!?;:)]$/);return match?{target:value.slice(0,-1),punctuation:match[0]}:{target:value,punctuation:""}};
function remarkLinkify(){
  return (tree:any)=>{
    const visit=(node:any)=>{
      if(!Array.isArray(node.children))return;
      const children:any[]=[];
      for(const child of node.children){
        if(child.type!=="text"){if(!["link","inlineCode","code","math","inlineMath","html"].includes(child.type))visit(child);children.push(child);continue}
        let last=0;
        for(const match of child.value.matchAll(MESSAGE_URL_PATTERN)){
          const index=match.index??0;
          if(index>last)children.push({type:"text",value:child.value.slice(last,index)});
          const {target,punctuation}=stripUrlPunctuation(match[0]);
          children.push({type:"link",url:target,children:[{type:"text",value:target}]});
          if(punctuation)children.push({type:"text",value:punctuation});
          last=index+match[0].length;
        }
        if(last<child.value.length)children.push({type:"text",value:child.value.slice(last)});
      }
      node.children=children;
    };
    visit(tree);
  };
}
const markdownComponents:any={
 a:({href,children,...props}:any)=><a {...props} className="message-link" href={href} target="_blank" rel="noopener noreferrer" onClick={e=>{e.preventDefault();if(!href)return;void openExternal(href).catch(()=>window.open(href,"_blank","noopener,noreferrer"))}}>{children}</a>,
 table:({children,...props}:any)=><div className="table-scroll" tabIndex={0}><table {...props} className="message-table">{children}</table></div>,
 pre:MessageCodeBlock,
 code:({className,children,...props}:any)=><code {...props} className={className}>{children}</code>,
};
const markdownUrlTransform=(url:string)=>/^(?:file:\/\/\/|\/(?:Users|private|tmp|var|Volumes)\/)/.test(url)?url:defaultUrlTransform(url);
// Some model responses have been observed to append a lone slash immediately
