// byte intact and remove only that unambiguous display artefact.
const normalizeMessageMarkdown=(value:string)=>value.replace(/(```[ \t]*)\/[ \t]*$/,"$1");
function MessageMarkdown({text,allowCollapse=false,stateKey,onDiagramEdit}:{text:string;allowCollapse?:boolean;stateKey?:string;onDiagramEdit?:(diagram:ConceptDiagram)=>void}){const extracted=extractDiagramBlocks(text);if(extracted.diagrams.length)return <><MessageMarkdown text={extracted.content} allowCollapse={allowCollapse} stateKey={stateKey}/>{extracted.diagrams.map((diagram,index)=><React.Suspense key={index} fallback={<p>概念図を読み込み中…</p>}><DiagramPreview diagram={diagram} onEdit={onDiagramEdit}/></React.Suspense>)}</>;if(allowCollapse&&text.length>LONG_PROMPT_LIMIT)return <LongPrompt text={text} stateKey={stateKey}/>;return <ReactMarkdown remarkPlugins={[remarkGfm,remarkMath,remarkLinkify]} rehypePlugins={[rehypeKatex]} urlTransform={markdownUrlTransform} components={markdownComponents}>{normalizeMessageMarkdown(text)}</ReactMarkdown>}
const LONG_PROMPT_LIMIT=5000;
function LongPrompt({text,stateKey}:{text:string;stateKey?:string}){const preview=text.replace(/\s+/g," ").trim().slice(0,120);return <ExpandableMessage stateKey={stateKey} preview={preview+(text.replace(/\s+/g," ").trim().length>120?"…":"")}><MessageMarkdown text={text} allowCollapse={false}/></ExpandableMessage>}
